                        raise ValueError(
                            f"bucket hit {index} must satisfy retain_from "
                            f"({self.retain_from}) <= index < size ({self.size})"
                        )
                    if index in assigned:
                        raise ValueError(
                            f"entry {index} is assigned to more than one bucket"
                        )
